@Component("paymentCard-handler")
@ProcessingGroup("paymentCard-processing-group")
public class PaymentCardEventHandler {
	
	// core constructor
	PaymentCardEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePaymentCardEvent
     */
    @EventHandler
    public void handle( CreatePaymentCardEvent event) {
        entityManager.persist(new PaymentCard(event.getPaymentCardId(), event.getCardToken(), event.getMaskedPan(), event.getExpiryMonth(), event.getExpiryYear(), event.getCardholderName(), event.getCustomer(), event.getAccount(), event.getTokenizations(), event.getDisputes(), event.getScheme(), event.getStatus()));
    }

    /*
     * @param	event UpdatePaymentCardEvent
     */
    @EventHandler
    public PaymentCard handle( UpdatePaymentCardEvent event) {
    	entityManager.merge(new PaymentCard(event.getPaymentCardId(), event.getCardToken(), event.getMaskedPan(), event.getExpiryMonth(), event.getExpiryYear(), event.getCardholderName(), event.getCustomer(), event.getAccount(), event.getTokenizations(), event.getDisputes(), event.getScheme(), event.getStatus()));
    }
    
    /*
     * @param	event DeletePaymentCardEvent
     */
    @EventHandler
    public void on( DeletePaymentCardEvent event) {
    	PaymentCard entity = new PaymentCard();
   
    	// ------------------------------------------
    	// apply the PaymentCardId
    	// ------------------------------------------
    	entity.setPaymentCardId( event.getPaymentCardId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PaymentCardRepository paymentCardEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PaymentCardEventHandler.class.getName());

}
